CREATE TABLE IF NOT EXISTS cards(id TEXT PRIMARY KEY,code_hash TEXT UNIQUE NOT NULL,prefix TEXT NOT NULL,plan TEXT NOT NULL,scenario TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'unused',expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL,order_id TEXT);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,card_id TEXT NOT NULL REFERENCES cards(id),email TEXT NOT NULL,plan TEXT NOT NULL,scenario TEXT NOT NULL,idempotency_key TEXT UNIQUE NOT NULL,status TEXT NOT NULL DEFAULT 'pending',task_id TEXT,reason TEXT NOT NULL DEFAULT '',charged INTEGER,subscription_succeeded INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,restored_at INTEGER);
CREATE TABLE IF NOT EXISTS mock_tasks(id TEXT PRIMARY KEY,order_id TEXT UNIQUE NOT NULL REFERENCES orders(id),idempotency_key TEXT UNIQUE NOT NULL,email TEXT NOT NULL,plan TEXT NOT NULL,scenario TEXT NOT NULL,ready_at INTEGER NOT NULL,verified INTEGER NOT NULL DEFAULT 0,resolution TEXT);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY,action TEXT NOT NULL,object_id TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS limits(bucket TEXT PRIMARY KEY,count INTEGER NOT NULL,reset_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS order_states ON orders(status);
